import { AlertTriangle } from "lucide-react";
import { CommentaryField } from "@/components/survey/CommentaryField";
import { calculateVariance, formatVariance } from "@/components/survey/surveyMath";
import type { SurveyNode } from "@/types/survey";

type DataRowProps = {
  node: SurveyNode;
  currentValue: string;
  commentary: string;
  isSelected: boolean;
  onCommentaryChange: (id: string, value: string) => void;
  onCurrentChange: (id: string, value: string) => void;
  onSelect: (node: SurveyNode) => void;
};

export function DataRow({
  node,
  currentValue,
  commentary,
  isSelected,
  onCommentaryChange,
  onCurrentChange,
  onSelect,
}: DataRowProps) {
  const variance = calculateVariance(node.prior, currentValue);
  const requiresCommentary = variance !== null && Math.abs(variance) > 15;
  const varianceColor =
    variance === null
      ? "text-survey-muted"
      : variance >= 0
        ? "text-survey-red"
        : "text-survey-green";

  return (
    <>
      <div
        aria-label={`Open details for ${node.name}`}
        className={[
          "survey-grid min-h-[44px] cursor-pointer border-b border-[#EEF0F3] px-4 text-[12px] leading-4 transition-colors max-[420px]:px-3",
          isSelected
            ? "bg-[#EAF4FF]"
            : requiresCommentary
              ? "bg-[#FFFDF6] hover:bg-[#FFF9ED]"
              : "bg-white hover:bg-[#F8FBFF]",
        ].join(" ")}
        onClick={() => onSelect(node)}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            onSelect(node);
          }
        }}
        role="button"
        tabIndex={0}
      >
        <div className="min-w-0 truncate pl-[54px] pr-3 text-[#223044] sm:pl-[56px]">
          {node.name}
        </div>
        <div className="text-right text-[12px] text-[#111827]">
          {node.prior?.toFixed(1)}
        </div>
        <div className="flex justify-center">
          <input
            aria-label={`${node.name} current value`}
            className={[
              "current-value-input h-7 rounded-md border bg-white px-2 text-center text-[11px] font-medium text-[#111827] outline-none transition focus:ring-2",
              requiresCommentary
                ? "border-[#F97316] focus:ring-orange-100"
                : "border-survey-border focus:border-[#B9C2D0] focus:ring-slate-100",
            ].join(" ")}
            inputMode="decimal"
            onChange={(event) => onCurrentChange(node.id, event.target.value)}
            type="number"
            step="0.1"
            value={currentValue}
          />
        </div>
        <div
          className={[
            "flex items-center justify-end gap-1.5 text-[12px] font-semibold",
            varianceColor,
          ].join(" ")}
        >
          <span>{formatVariance(variance)}</span>
          {requiresCommentary ? (
            <AlertTriangle className="h-4 w-4 text-[#F97316]" strokeWidth={1.8} />
          ) : null}
        </div>
      </div>

      {requiresCommentary ? (
        <CommentaryField
          onChange={(value) => onCommentaryChange(node.id, value)}
          value={commentary}
        />
      ) : null}
    </>
  );
}
