export function calculateVariance(prior = 0, currentValue: string | number) {
  const current =
    typeof currentValue === "number"
      ? currentValue
      : Number.parseFloat(currentValue);

  if (!Number.isFinite(current) || prior === 0) {
    return null;
  }

  return ((current - prior) / prior) * 100;
}

export function formatVariance(variance: number | null) {
  if (variance === null) {
    return "-";
  }

  const prefix = variance > 0 ? "+" : "";
  return `${prefix}${variance.toFixed(1)}%`;
}
